<?php
namespace App\Services;
use App\Jobs\DeliverErpNotification; use App\Models\{ApprovalAction,ApprovalDefinition,ApprovalRequest,ApprovalStep,ApprovalDelegation,ErpNotification,PlatformAuditLog,RoleAssignment,User}; use App\Support\Decimal; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class ApprovalService {
 public function create(array $data):ApprovalRequest{return DB::transaction(function()use($data){$definition=ApprovalDefinition::where('tenant_id',$data['tenant_id'])->where('scenario',$data['scenario'])->where('is_active',true)->when($data['company_id']??null,fn($q)=>$q->where(fn($x)=>$x->whereNull('company_id')->orWhere('company_id',$data['company_id'])))->with('steps')->firstOrFail();$step=$definition->steps->first(fn($s)=>Decimal::compare((string)$data['amount'],(string)$s->minimum_amount)>=0&&($s->maximum_amount===null||Decimal::compare((string)$data['amount'],(string)$s->maximum_amount)<=0)&&(!$s->department_id||$s->department_id===($data['department_id']??null)));if(!$step)throw ValidationException::withMessages(['approval'=>['No approval rule matches this amount and department.']]);$request=ApprovalRequest::create(['tenant_id'=>$data['tenant_id'],'definition_id'=>$definition->id,'requester_id'=>$data['requester_id'],'company_id'=>$data['company_id']??null,'department_id'=>$data['department_id']??null,'document_type'=>$data['document_type'],'document_id'=>$data['document_id'],'amount'=>$data['amount'],'current_level'=>$step->level,'state'=>'pending']);$this->notifyEligible($request,$step);return $request;});}
 public function decide(ApprovalRequest $request,User $actor,string $decision,?string $comment=null):ApprovalRequest{return DB::transaction(function()use($request,$actor,$decision,$comment){$request=ApprovalRequest::whereKey($request->id)->with(['definition.steps'])->lockForUpdate()->firstOrFail();if($request->state!=='pending')throw ValidationException::withMessages(['state'=>['This approval request is no longer pending.']]);$step=$request->definition->steps->firstWhere('level',$request->current_level);if(!$step||!$this->canAct($request,$step,$actor))abort(403,'You are not an eligible approver.');if(!$request->definition->allow_self_approval&&$request->requester_id===$actor->id)abort(403,'Self-approval is prohibited by policy.');ApprovalAction::create(['tenant_id'=>$request->tenant_id,'approval_request_id'=>$request->id,'approver_id'=>$actor->id,'level'=>$request->current_level,'decision'=>$decision,'comment'=>$comment,'acted_at'=>now()]);if($decision==='rejected')$request->update(['state'=>'rejected','completed_at'=>now()]);else{$next=$request->definition->steps->first(fn($s)=>$s->level>$request->current_level&&Decimal::compare((string)$request->amount,(string)$s->minimum_amount)>=0&&($s->maximum_amount===null||Decimal::compare((string)$request->amount,(string)$s->maximum_amount)<=0)&&(!$s->department_id||$s->department_id===$request->department_id));if($next)$request->update(['current_level'=>$next->level]);else$request->update(['state'=>'approved','completed_at'=>now()]);if($next)$this->notifyEligible($request->fresh(),$next);}return $request->fresh('actions');});}
 public function eligible(ApprovalRequest $request,User $candidate,ApprovalStep $step):bool{$auth=app(AuthorizationService::class);if($request->department_id&&$step->department_id&&$request->department_id!==$step->department_id)return false;if($auth->allows($candidate,$request->tenant_id,$step->permission,$request->company_id,null,$step->department_id))return true;return ApprovalDelegation::where('tenant_id',$request->tenant_id)->where('delegate_id',$candidate->id)->where('is_active',true)->where('starts_at','<=',now())->where('ends_at','>=',now())->when($request->definition->scenario,fn($q)=>$q->where(fn($x)=>$x->whereNull('scenario')->orWhere('scenario',$request->definition->scenario)))->whereExists(fn($q)=>$q->from('role_assignments')->whereColumn('role_assignments.user_id','approval_delegations.delegator_id')->where('role_assignments.tenant_id',$request->tenant_id))->exists();}
 private function canAct(ApprovalRequest $request,ApprovalStep $step,User $actor):bool{return $this->eligible($request,$actor,$step);}
 private function notifyEligible(ApprovalRequest $request,ApprovalStep $step):void{User::whereHas('tenantMemberships',fn($q)=>$q->where('tenant_id',$request->tenant_id)->where('status','active'))->get()->each(function($user)use($request,$step){if($this->eligible($request,$user,$step)){$notification=ErpNotification::create(['tenant_id'=>$request->tenant_id,'user_id'=>$user->id,'type'=>'approval.requested','title'=>'Approval required','body'=>'A '.$request->document_type.' requires your approval.','delivery_state'=>'pending']);DeliverErpNotification::dispatch($request->tenant_id,$notification->id);}});}
}
